import re

def valid_code(value):
    return re.fullmatch(r"[A-Z]{3}-[0-9]{3}", value) is not None

def write_all(stream, data):
    total_length = len(data)
    view = memoryview(data)
    offset = 0
    while offset < total_length:
        n_written = stream.write(view[offset:])
        if n_written is None:
            continue
        if n_written == 0:
            raise BlockingIOError("stream.write returned zero bytes")
        offset += n_written
    return total_length

