def write_all(stream, data):
    total_length = len(data)
    if total_length == 0:
        return 0
    view = memoryview(data)
    offset = 0
    while offset < total_length:
        n = stream.write(view[offset:])
        if n is None or n == 0:
            raise BlockingIOError("write() returned zero or None")
